import { TAG_ASIDE, TAG_BUTTON, TAG_EMBED, TAG_FIELDSET, TAG_FIGURE, TAG_FOOTER, TAG_FORM, TAG_IFRAME, TAG_INPUT, TAG_NAV, TAG_OBJECT, TAG_SELECT, TAG_TEXTAREA } from "./extraction-D28Kr1J3.mjs";
import { filterPlugin, frontmatterPlugin, isolateMainPlugin, tailwindPlugin } from "./plugins-DXY-fo9h.mjs";

//#region src/preset/minimal.ts
/**
* Creates a configurable minimal preset with advanced options
*
* @param options HTML to Markdown options
* @returns HTML to Markdown options with configured plugins
*/
function withMinimalPreset(options = {}) {
	const plugins = [
		frontmatterPlugin(),
		isolateMainPlugin(),
		tailwindPlugin(),
		filterPlugin({ exclude: [
			TAG_FORM,
			TAG_FIELDSET,
			TAG_OBJECT,
			TAG_EMBED,
			TAG_FIGURE,
			TAG_FOOTER,
			TAG_ASIDE,
			TAG_IFRAME,
			TAG_INPUT,
			TAG_TEXTAREA,
			TAG_SELECT,
			TAG_BUTTON,
			TAG_NAV
		] })
	];
	if (options.plugins) plugins.push(...options.plugins);
	return {
		...options,
		plugins
	};
}

//#endregion
export { withMinimalPreset };